const body = $input.first().json.body || $input.first().json;
const query = String(body.query || body.q || '').trim();
if (!query) {
  return [{ json: { ok: false, error: 'missing_query', message: 'search_customers requires { query }.', results: [], _status: 400 } }];
}
const q = query.toLowerCase();
const results = customers.filter(c => [c.name, c.email, c.company, c.customer_id].filter(Boolean).join(' ').toLowerCase().includes(q));
return [{ json: { ok: true, query, match_count: results.length, results, ...(results.length > 1 ? { warning: 'Multiple customers matched. Disambiguate before list_orders / create_ticket.' } : {}), _status: 200 } }];
